using LocalChat;
using System.Diagnostics;
int checks=0;void Check(bool ok){if(!ok)throw new Exception("check "+(checks+1));checks++;}void Throws(Action a){try{a();}catch(ArgumentException){checks++;return;}throw new Exception("Expected exception");}
Check(VideoRecipe.Manifest(1).Contains("duration 3"));Check(VideoRecipe.Manifest(60).Split("duration 3").Length==61);Check(!VideoRecipe.Manifest(2).Contains("file:/"));Throws(()=>VideoRecipe.Manifest(0));Throws(()=>VideoRecipe.Manifest(61));Throws(()=>VideoRecipe.Arguments("relative","/tmp/out.mp4",1));Throws(()=>VideoRecipe.Arguments("/tmp/in","/tmp/out.avi",1));var options=VideoRecipe.Arguments("/tmp/a b/frames.ffconcat","/tmp/a b/out.mp4",2);Check(options.Contains("-n"));Check(options.Contains("-nostdin"));Check(options.Contains("libx264"));Check(options.Contains("file"));Check(options.Contains("6"));Check(options.Contains("/tmp/a b/out.mp4"));Check(!options.Contains("-y"));
var root=Path.Combine(Path.GetTempPath(),"nora-video-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string png=Path.Combine(root,"frame-000.png"),manifest=Path.Combine(root,"frames.ffconcat"),output=Path.Combine(root,"out.mp4");var start=new ProcessStartInfo("/usr/local/bin/ffmpeg"){UseShellExecute=false,RedirectStandardError=true};foreach(var a in new[]{"-hide_banner","-f","lavfi","-i","color=c=blue:s=1280x720","-frames:v","1","-threads","1",png})start.ArgumentList.Add(a);using(var p=Process.Start(start)!){await p.StandardError.ReadToEndAsync();await p.WaitForExitAsync();Check(p.ExitCode==0);}File.WriteAllText(manifest,VideoRecipe.Manifest(1),new System.Text.UTF8Encoding(false));await VideoRecipe.Render("/usr/local/bin/ffmpeg",manifest,output,1,CancellationToken.None);Check(File.Exists(output));Check(new FileInfo(output).Length>32);try{await VideoRecipe.Render("/usr/local/bin/ffmpeg",manifest,output,1,CancellationToken.None);throw new Exception("overwrite allowed");}catch(IOException){checks++;}string failed=Path.Combine(root,"failed.mp4");using var cancel=new CancellationTokenSource();cancel.Cancel();try{await VideoRecipe.Render("/usr/local/bin/ffmpeg",manifest,failed,1,cancel.Token);throw new Exception("cancel ignored");}catch(OperationCanceledException){checks++;}Check(!File.Exists(failed));}finally{Directory.Delete(root,true);}Console.WriteLine($"Video: {checks} checks passed (real FFmpeg Linux smoke included)");
